-- Initial schema: SPEC.md §5, excluding the Phase 4 (key_slots) and Phase 5
-- (yjs_updates) tables. Identifiers are UUIDv7 generated by the server.
--
-- Migrations are forward-only and must stay backward-compatible with the
-- previous release (SPEC.md §12). Never edit a migration once released; add a
-- new one instead.

CREATE TABLE users (
    id            uuid        PRIMARY KEY,
    oidc_issuer   text        NOT NULL CHECK (oidc_issuer <> ''),
    oidc_subject  text        NOT NULL CHECK (oidc_subject <> ''),
    display_name  text        NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_oidc_identity_key UNIQUE (oidc_issuer, oidc_subject)
);

CREATE TABLE devices (
    id          uuid        PRIMARY KEY,
    user_id     uuid        NOT NULL REFERENCES users (id),
    name        text        NOT NULL,
    -- X25519 public key; used by end-to-end encryption (SPEC.md §9.3).
    public_key  bytea       CONSTRAINT devices_public_key_length CHECK (octet_length(public_key) = 32),
    last_seen   timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX devices_user_id_idx ON devices (user_id);

CREATE TABLE vaults (
    id          uuid        PRIMARY KEY,
    name        text        NOT NULL CHECK (name <> ''),
    encryption  text        NOT NULL CONSTRAINT vaults_encryption_valid CHECK (encryption IN ('none', 'e2ee')),
    escrow      boolean     NOT NULL DEFAULT false,
    -- Vault-wide change counter; revisions.seq is assigned from it.
    head_seq    bigint      NOT NULL DEFAULT 0 CONSTRAINT vaults_head_seq_nonnegative CHECK (head_seq >= 0),
    created_at  timestamptz NOT NULL DEFAULT now(),
    -- Escrow wraps E2EE epoch keys (SPEC.md §9.4); it is meaningless otherwise.
    CONSTRAINT vaults_escrow_requires_e2ee CHECK (NOT escrow OR encryption = 'e2ee')
);

CREATE TABLE vault_members (
    vault_id    uuid        NOT NULL REFERENCES vaults (id),
    user_id     uuid        NOT NULL REFERENCES users (id),
    role        text        NOT NULL CONSTRAINT vault_members_role_valid CHECK (role IN ('owner', 'editor', 'viewer')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (vault_id, user_id)
);

CREATE INDEX vault_members_user_id_idx ON vault_members (user_id);

CREATE TABLE blobs (
    vault_id    uuid        NOT NULL REFERENCES vaults (id),
    -- SHA-256 (plaintext vaults) or HMAC-SHA256 (E2EE vaults) of the content.
    blob_id     bytea       NOT NULL CONSTRAINT blobs_blob_id_length CHECK (octet_length(blob_id) = 32),
    size        bigint      NOT NULL CONSTRAINT blobs_size_nonnegative CHECK (size >= 0),
    state       text        NOT NULL CONSTRAINT blobs_state_valid CHECK (state IN ('uploading', 'complete')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (vault_id, blob_id)
);

CREATE TABLE documents (
    id           uuid        PRIMARY KEY,
    vault_id     uuid        NOT NULL REFERENCES vaults (id),
    kind         text        NOT NULL CONSTRAINT documents_kind_valid CHECK (kind IN ('blob', 'text', 'yjs')),
    -- Every document has a head revision. The foreign key (added below) is
    -- deferred so a document and its first revision can be inserted in one
    -- transaction.
    head_rev_id  uuid        NOT NULL,
    -- Normalized path (NFC, then case-folded) or, for E2EE vaults, its HMAC.
    path_key     text        NOT NULL CONSTRAINT documents_path_key_length CHECK (octet_length(path_key) BETWEEN 1 AND 8192),
    -- Mirrors the head revision's tombstone flag; only live documents take
    -- part in path_key uniqueness.
    deleted      boolean     NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT documents_id_vault_id_key UNIQUE (id, vault_id)
);

-- path_key is unique per vault among live documents (SPEC.md §5).
CREATE UNIQUE INDEX documents_live_path_key_idx ON documents (vault_id, path_key) WHERE NOT deleted;

CREATE TABLE revisions (
    id             uuid        PRIMARY KEY,
    document_id    uuid        NOT NULL,
    vault_id       uuid        NOT NULL,
    -- Position in the vault's change feed, assigned from vaults.head_seq.
    seq            bigint      NOT NULL CONSTRAINT revisions_seq_positive CHECK (seq > 0),
    parent_rev_id  uuid,
    -- blob_id of the content; absent only for tombstones.
    content_ref    bytea,
    -- Plaintext path, or encoded ciphertext for E2EE vaults.
    path           text        NOT NULL CONSTRAINT revisions_path_length CHECK (octet_length(path) BETWEEN 1 AND 8192),
    deleted        boolean     NOT NULL DEFAULT false,
    device_id      uuid        NOT NULL REFERENCES devices (id),
    created_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT revisions_vault_id_seq_key UNIQUE (vault_id, seq),
    CONSTRAINT revisions_id_document_id_key UNIQUE (id, document_id),
    -- A revision belongs to a document in the same vault.
    CONSTRAINT revisions_document_fkey FOREIGN KEY (document_id, vault_id)
        REFERENCES documents (id, vault_id),
    -- A parent revision belongs to the same document.
    CONSTRAINT revisions_parent_fkey FOREIGN KEY (parent_rev_id, document_id)
        REFERENCES revisions (id, document_id),
    -- Content is a blob in the same vault; a referenced blob cannot be dropped.
    CONSTRAINT revisions_content_fkey FOREIGN KEY (vault_id, content_ref)
        REFERENCES blobs (vault_id, blob_id),
    -- A live revision always has content.
    CONSTRAINT revisions_live_has_content CHECK (deleted OR content_ref IS NOT NULL)
);

CREATE INDEX revisions_document_id_seq_idx ON revisions (document_id, seq);

-- The head revision belongs to the document itself.
ALTER TABLE documents
    ADD CONSTRAINT documents_head_rev_fkey FOREIGN KEY (head_rev_id, id)
        REFERENCES revisions (id, document_id) DEFERRABLE INITIALLY DEFERRED;
